'use client';

import { HeroBanner } from '@/components/customer/HeroBanner';
import { ServiceCard } from '@/components/customer/ServiceCard';
import { ProductCard } from '@/components/customer/ProductCard';
import { PromoCarousel } from '@/components/customer/PromoCarousel';
import { Section } from '@/components/shared/layout/Section'; // OUR NEW COMPONENT
import { Button } from '@/components/ui/button';
import { CustomerRoutes } from '@/lib/constants/routes';
import Link from 'next/link';
import { useServices } from '@/api/domains/services/queries';
import { useProducts } from '@/api/domains/products/queries';
import { ArrowRight, Sparkles, Users, Award, TrendingUp } from 'lucide-react';
import Loading from '@/components/shared/display/Loading';
import { mockTrustStats, mockBanners } from '@/mocks/data/customer-mock-data';

// Define icon map outside component to avoid recreation on render
const ICON_MAP = {
  users: Users,
  award: Award,
  trending: TrendingUp
};

export default function HomePage() {
  const { data: servicesResponse, isLoading: servicesLoading } = useServices({ limit: 3 });
  const { data: productsResponse, isLoading: productsLoading } = useProducts({ limit: 4 });
  
  const services = servicesResponse?.data || [];
  const products = productsResponse?.data || [];
  
  const promos = mockBanners.slice(0, 2).map(banner => ({
    id: banner.id,
    title: banner.title,
    description: banner.subtitle || 'Limited time offer',
    image: banner.imageUrl || '',
    link: banner.ctaLink || '/services',
    ctaText: banner.ctaText || 'Learn More',
  }));

  if (servicesLoading || productsLoading) return <Loading />;

  return (
    <main className="bg-background min-h-screen">
      <HeroBanner />

      {/* Promos - Use muted variant for subtle contrast */}
      <Section variant="muted" className="py-12 md:py-16">
        <PromoCarousel promos={promos} />
      </Section>

      {/* Services - Clean white background with grid pattern */}
      <Section withPattern>
        <div className="flex flex-col md:flex-row md:items-end justify-between mb-12 gap-6">
          <div className="max-w-2xl space-y-4">
            <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-primary/10 text-primary text-sm font-medium">
              <Sparkles className="h-4 w-4" />
              <span>Our Expertise</span>
            </div>
            <h2 className="text-h2">Featured Services</h2>
            <p className="text-body text-lg">
              Premium car care services delivered with excellence.
            </p>
          </div>
          <Button asChild size="lg" variant="ghost" className="group">
            <Link href={CustomerRoutes.SERVICES}>
              View All Services
              <ArrowRight className="ml-2 h-4 w-4 transition-transform group-hover:translate-x-1" />
            </Link>
          </Button>
        </div>
        
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {services.map((service) => (
            <ServiceCard key={service.id} service={service as any} />
          ))}
        </div>
      </Section>

      {/* Products - Muted background for separation */}
      <Section variant="muted">
        <div className="flex flex-col md:flex-row md:items-end justify-between mb-12 gap-6">
          <div className="space-y-4">
            <h2 className="text-h2">Popular Products</h2>
            <p className="text-body text-lg">Professional quality care for your home.</p>
          </div>
          <Button asChild variant="outline">
            <Link href={CustomerRoutes.PRODUCTS}>Shop All Products</Link>
          </Button>
        </div>
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
          {products.map((product) => (
            <ProductCard key={product._id} product={product as any} />
          ))}
        </div>
      </Section>

      {/* Trust Stats - Primary brand color background */}
      <Section variant="primary" className="text-center">
        <div className="max-w-3xl mx-auto mb-16 space-y-4">
          <h2 className="text-h2 text-white">Trusted by Thousands</h2>
          <p className="text-primary-foreground/80 text-lg">
            Join our community of satisfied customers who trust us with their vehicles.
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
          {mockTrustStats.map((stat) => {
            const Icon = ICON_MAP[stat.icon as keyof typeof ICON_MAP] || Users;
            return (
              <div key={stat.id} className="p-6 rounded-2xl bg-white/10 backdrop-blur-sm border border-white/10">
                <div className="inline-flex p-4 rounded-xl bg-white/20 mb-4">
                  <Icon className="h-8 w-8 text-white" />
                </div>
                <div className="text-5xl font-bold mb-2 text-white">{stat.value}</div>
                <div className="text-primary-foreground/80 font-medium">{stat.label}</div>
              </div>
            );
          })}
        </div>
      </Section>
    </main>
  );
}
